SELECT c.relname AS tabla, t.tgname AS trigger, t.tgenabled, p.proname AS funcion FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_proc p ON p.oid=t.tgfoid WHERE n.nspname='public' AND NOT t.tgisinternal AND (p.proname LIKE '%truncate%' OR p.proname LIKE 'fin_trg%' OR c.relname='transactions' OR c.relname='stores') ORDER BY c.relname, t.tgname;
